 if(!epub){const r=canvas.getBoundingClientRect();if(rectIntersects(r,rect)){x.drawImage(canvas,(rect.left-r.left)*canvas.width/r.width,(rect.top-r.top)*canvas.height/r.height,rect.width*canvas.width/r.width,rect.height*canvas.height/r.height,0,0,c.width,c.height);found=true}}
