 B('betaSelection').onpointerdown=e=>{if(e.button!==0||!e.isPrimary)return;e.preventDefault();gesture={x:e.clientX,y:e.clientY};e.currentTarget.setPointerCapture(e.pointerId)};
 B('betaSelection').onpointermove=e=>{if(!gesture)return;const r=e.currentTarget.getBoundingClientRect(),x=e.currentTarget.getContext('2d');x.clearRect(0,0,r.width,r.height);x.fillStyle='#253b3840';x.fillRect(0,0,r.width,r.height);x.clearRect(Math.min(gesture.x,e.clientX)-r.left,Math.min(gesture.y,e.clientY)-r.top,Math.abs(gesture.x-e.clientX),Math.abs(gesture.y-e.clientY));x.strokeStyle='#a83c35';x.lineWidth=2;x.strokeRect(Math.min(gesture.x,e.clientX)-r.left,Math.min(gesture.y,e.clientY)-r.top,Math.abs(gesture.x-e.clientX),Math.abs(gesture.y-e.clientY));};
 B('betaSelection').onpointerup=e=>{if(!gesture)return;const g=gesture;resetSelection();const r={left:Math.min(g.x,e.clientX),top:Math.min(g.y,e.clientY),right:Math.max(g.x,e.clientX),bottom:Math.max(g.y,e.clientY),width:Math.abs(g.x-e.clientX),height:Math.abs(g.y-e.clientY)};B('betaDialog').showModal();if(r.width<15||r.height<15){message('15px 이상의 영역을 드래그해 주세요.');return}const selected=capture(r);crop=selected.image;B('betaSource').value=selected.text;B('betaOutput').textContent='';B('betaPreview').hidden=!crop;if(crop)B('betaPreview').src=crop.toDataURL();message(crop?'선택 완료. OCR 또는 OCR+번역을 누르세요.':selected.text?'텍스트 EPUB에서 원문을 추출했습니다. 원문 번역을 누르세요.':'선택 영역에서 글자·이미지를 찾지 못했습니다.');};B('betaSelection').onpointercancel=()=>{resetSelection();B('betaDialog').showModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&selecting){e.preventDefault();e.stopPropagation();resetSelection();B('betaDialog').showModal()}});
